                   grad_norm_weight, hc_eps);
  return NineTensorRefs(grad_residual, grad_phi, grad_alpha, grad_bias, grad_previous_output, grad_previous_pre,
                        grad_previous_post, grad_previous_residual, grad_norm_weight);
